// Generated by Cypress Author — 2026-10-01
describe('Établissement — recherche', () => {
    beforeEach(() => {
        cy.login()
    })

    const activityGroupToggle = (label) => cy.get('#type_span [data-cy="activity-group-toggle"]')
        .filter((_, button) => button.textContent.trim() === label)

    const activityGroup = (label) => cy.get("select[name='types_activites[]']").then(($select) => {
        const group = Array.from($select[0].querySelectorAll('optgroup'))
            .find((optgroup) => optgroup.label.trim() === label)

        expect(group, `Groupe d'activités ${label}`).to.exist

        return {
            values: Array.from(group.querySelectorAll('option')).map((option) => option.value),
            firstLabel: group.querySelector('option')?.textContent.trim(),
        }
    })

    const openActivityFilter = () => {
        cy.visit('/rechercher/etablissement?genres%5B%5D=2')
        cy.get('#type_span').should('be.visible')
        cy.get('#type_span .ts-control').click()
    }

    it('Page chargée → formulaire de recherche visible', () => {
        cy.visit('/rechercher/etablissement')
        cy.contains('Etablissements').should('exist');
        cy.get('[name=Rechercher]').should('exist');
    });

    // Use URL query params to filter by avis — avoids fragile jQuery Multiselect interactions.
    it('Filtre "Avis favorable" → seuls les établissements favorables affichés', () => {
        cy.visit('/rechercher/etablissement?avis[]=true')
        cy.get('.avis.F').should('exist')
        cy.get('.avis.D').should('not.exist')
    });

    it('Filtre "Avis défavorable" → seuls les établissements défavorables affichés', () => {
        cy.visit('/rechercher/etablissement?avis[]=false')
        cy.get('.avis.D').should('exist')
        cy.get('.avis.F').should('not.exist')
    });

    it('Cliquer sur un type → sélectionne toutes ses activités et permet de les désélectionner', () => {
        openActivityFilter()

        activityGroup('L').then(({ values }) => {
            expect(values.length).to.be.greaterThan(1)

            activityGroupToggle('L').find('.glyphicon-list').should('have.attr', 'aria-hidden', 'true')
            activityGroupToggle('L').click()
            activityGroupToggle('L').find('.glyphicon-list').should('exist')
            cy.get("select[name='types_activites[]']").should(($select) => {
                expect(Array.from($select[0].selectedOptions).map((option) => option.value)).to.have.members(values)
            })

            cy.get('input.btn_search[name=Rechercher]').click()
            cy.location().should((location) => {
                expect(new URLSearchParams(location.search).getAll('types_activites[]')).to.have.members(values)
            })

            cy.get('#type_span .ts-control').click()
            activityGroupToggle('L').click()
            cy.get("select[name='types_activites[]']").should(($select) => {
                expect(Array.from($select[0].selectedOptions)).to.have.length(0)
            })
        })
    })

    it('Sélectionner une activité puis cliquer sur le type → complète la sélection du groupe', () => {
        openActivityFilter()

        activityGroup('L').then(({ values }) => {
            const firstValue = values[0]
            cy.get(`#type_span .ts-dropdown .option[data-value="${firstValue}"]`).click()
            activityGroupToggle('L').click()
            cy.get("select[name='types_activites[]']").should(($select) => {
                expect(Array.from($select[0].selectedOptions).map((option) => option.value)).to.have.members(values)
            })
        })
    })

    it('Barre espace sur un type → sélectionne toutes ses activités', () => {
        openActivityFilter()

        activityGroup('L').then(({ values }) => {
            activityGroupToggle('L').focus().should('have.focus')
            cy.press(Cypress.Keyboard.Keys.SPACE)
            cy.get("select[name='types_activites[]']").should(($select) => {
                const selectedValues = Array.from($select[0].selectedOptions).map((option) => option.value)
                expect(selectedValues).to.have.members(values)
            })
        })
    })

    it('Filtrer les activités puis cliquer sur un type → sélectionne aussi ses activités masquées', () => {
        openActivityFilter()

        activityGroup('L').then(({ values, firstLabel }) => {
            expect(firstLabel).to.be.a('string').and.not.be.empty
            cy.get('#type_span .ts-control input').type(firstLabel)
            cy.get('#type_span .ts-dropdown .option[data-value]').should(($options) => {
                expect($options.length).to.be.lessThan(values.length)
            })

            activityGroupToggle('L').click()
            cy.get("select[name='types_activites[]']").should(($select) => {
                const selectedValues = Array.from($select[0].selectedOptions).map((option) => option.value)
                expect(selectedValues).to.have.members(values)
            })
        })
    })
});
